def short(prefix,items):return [f'{prefix}{i}: {text}' for i,text in enumerate(items,1)]
def build_context(c):return {'dx':short('D',c['dx']),'px':short('P',c['px']),'lab':short('L',c['lab'][:20])}
def parse_context(ctx):
 out={};kinds={'dx':'diagnosis','px':'procedure','lab':'lab'}
 for key,kind in kinds.items():
  for item in ctx[key]:
   m=PATTERN.fullmatch(item)
   if not m:raise ValueError(f'Invalid compact context item: {item}')
   out[m.group(1)]={'anchor_type':kind,'anchor_string':m.group(2)}
 return out
def restore_single_anchor(record,mapping):
 if 'anchor_ids' in record:return [],False,'schema_error_anchor_ids_array_forbidden'
