def main():
 OUT.mkdir(parents=True,exist_ok=True);selected_hash=sha(SELECTED) if SELECTED.exists() else None;source_hash=sha(SOURCE);cases,used,input_path=base.load_cases();old=load_chars(OLD);compact=load_chars(COMPACT);contextid=load_chars(CONTEXT_ID);prompts=[];views=[];problems=[]
 for i,c in enumerate(cases,1):
  pid=f'test20_case_{i:03d}';ctx=build_context(c);mapping=parse_context(ctx);target=[f"{m['medication']}|{m['medication_function']}" for m in base.choose_meds(c)];user_obj={'case':{'stay_id':c['stay_id'],'hospital_id':c['hospital_id'],'age':c['age'],'sex':c['sex']},'context':ctx,'target_medications':target,'task':TASK,'output':OUTPUT};user=json.dumps(user_obj,ensure_ascii=False,allow_nan=False,separators=(',',':'));chars=len(SYSTEM_PROMPT)+len(user);oldc=old.get(c['stay_id'],0);compactc=compact.get(c['stay_id'],0);contextc=contextid.get(c['stay_id'],0);reduction=oldc-chars if oldc else 0;rate=reduction/oldc if oldc else 0.0
  row={'prompt_id':pid,'stay_id':c['stay_id'],'hospital_id':c['hospital_id'],'num_dx':len(ctx['dx']),'num_px':len(ctx['px']),'num_lab':len(ctx['lab']),'num_med':len(c['med']),'num_target_meds':len(target),'num_context_ids':len(mapping),'target_medications':target,'context':ctx,'anchor_id_map':mapping,'system_prompt':SYSTEM_PROMPT,'user_prompt':user,'estimated_prompt_chars':chars,'old_estimated_prompt_chars':oldc,'compact_estimated_prompt_chars':compactc,'context_id_estimated_prompt_chars':contextc,'char_reduction_vs_old':reduction,'char_reduction_rate_vs_old':rate,'dry_run_only':True};prompts.append(row);views.append({'prompt_id':pid,'stay_id':c['stay_id'],'hospital_id':c['hospital_id'],'target_medications':target,'context':ctx,'anchor_id_map':mapping})
  allitems=[(x,'D') for x in ctx['dx']]+[(x,'P') for x in ctx['px']]+[(x,'L') for x in ctx['lab']];ids=[];invalid=False
  for item,prefix in allitems:
   m=PATTERN.fullmatch(item);invalid|=not bool(m) or not m.group(1).startswith(prefix)
