  oldrate=(p['old_estimated_prompt_chars']-p['estimated_prompt_chars'])/p['old_estimated_prompt_chars'] if p['old_estimated_prompt_chars'] else 0;ctxrate=(p['context_id_estimated_prompt_chars']-p['estimated_prompt_chars'])/p['context_id_estimated_prompt_chars'] if p['context_id_estimated_prompt_chars'] else 0
  md += [f'## Prompt {i}','','### Metadata',f"- stay_id: {p['stay_id']}",f"- hospital_id: {p['hospital_id']}",f"- old chars: {p['old_estimated_prompt_chars']}",f"- context-id chars: {p['context_id_estimated_prompt_chars']}",f"- min-token chars: {p['estimated_prompt_chars']}",f"- reduction rate vs old: {oldrate:.2%}",f"- reduction rate vs context-id: {ctxrate:.2%}",f"- num_dx: {p['num_dx']}",f"- num_px: {p['num_px']}",f"- num_lab: {p['num_lab']}",f"- num_context_ids: {p['num_context_ids']}",f"- num_target_meds: {p['num_target_meds']}",'','### Context','',json.dumps(p['context'],ensure_ascii=False,indent=2),'','### System Prompt','',p['system_prompt'],'','### User Prompt','','```json',json.dumps(json.loads(p['user_prompt']),ensure_ascii=False,indent=2),'```','']
